diffs.replacement:
import React, { useState, useEffect, useMemo } from 'react';
import { BookMarked, Sparkles, Send, Tag, Settings as SettingsIcon, Library, Globe, BarChart2, Feather, SquareStack } from 'lucide-react';
import { LANGUAGES, LEVELS, LEVEL_SPECIFIC_TOPICS, STORY_STYLES, LEVEL_DESCRIPTIONS, STORY_STYLE_LABELS, APP_LANGUAGES, LANGUAGE_LABELS, LANGUAGE_THEMES } from './constants';
import { Language, CEFRLevel, GenerationState, StoryStyle, StoryResponse, AppLanguage, SavedStory, Theme, SavedFlashCard } from './types';
import { Selector } from './components/Selector';
import { StoryDisplay } from './components/StoryDisplay';
import { LoadingState } from './components/LoadingState';
import { SettingsModal } from './components/SettingsModal';
import { SavedStoriesModal } from './components/SavedStoriesModal';
import { SavedFlashCardsModal } from './components/SavedFlashCardsModal';
import { generateStory } from './services/geminiService';
import { TRANSLATIONS } from './translations';

const STORAGE_KEYS = {
  LANGUAGE: 'linguatale_pref_language',
  LEVEL: 'linguatale_pref_level',
  STYLE: 'linguatale_pref_style',
  APP_LANGUAGE: 'linguatale_app_language',
  SAVED_STORIES: 'linguatale_saved_stories',
  SAVED_FLASHCARDS: 'linguatale_saved_flashcards',
  THEME: 'linguatale_theme',
  SHOW_QUIZ: 'linguatale_show_quiz',
  SHOW_FLASHCARDS: 'linguatale_show_flashcards'
};

const App: React.FC = () => {
  const [appLanguage, setAppLanguage] = useState<AppLanguage>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.APP_LANGUAGE);
    return (saved && APP_LANGUAGES.includes(saved as AppLanguage)) ? (saved as AppLanguage) : "English";
  });

  const [theme, setTheme] = useState<Theme>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.THEME);
    if (saved === 'dark' || saved === 'light') return saved;
    return 'light';
  });

  const [showQuiz, setShowQuiz] = useState<boolean>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.SHOW_QUIZ);
    return saved !== null ? JSON.parse(saved) : true;
  });

  const [showFlashCards, setShowFlashCards] = useState<boolean>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.SHOW_FLASHCARDS);
    return saved !== null ? JSON.parse(saved) : true;
  });

  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isLibraryOpen, setIsLibraryOpen] = useState(false);
  const [isFlashCardsOpen, setIsFlashCardsOpen] = useState(false);

  // Immersive Focus Mode State
  const [isFocused, setIsFocused] = useState(false);

  const t = TRANSLATIONS[appLanguage] || TRANSLATIONS["English"];
  const levelDescriptions = LEVEL_DESCRIPTIONS[appLanguage] || LEVEL_DESCRIPTIONS["English"];
  const storyStyleLabels = STORY_STYLE_LABELS[appLanguage] || STORY_STYLE_LABELS["English"];
  const languageLabels = LANGUAGE_LABELS[appLanguage] || LANGUAGE_LABELS["English"];

  const [language, setLanguage] = useState<Language>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.LANGUAGE);
    return (saved && LANGUAGES.includes(saved as Language)) ? (saved as Language) : "English";
  });

  const [level, setLevel] = useState<CEFRLevel>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.LEVEL);
    return (saved && LEVELS.includes(saved as CEFRLevel)) ? (saved as CEFRLevel) : "A1.1";
  });

  const [storyStyle, setStoryStyle] = useState<StoryStyle>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.STYLE);
    return (saved && STORY_STYLES.includes(saved as StoryStyle)) ? (saved as StoryStyle) : "Standard";
  });

  const [storyDescription, setStoryDescription] = useState<string>("");

  const [storyHistory, setStoryHistory] = useState<StoryResponse[]>([]);
  const [currentIndex, setCurrentIndex] = useState(-1);

  const [isGenerating, setIsGenerating] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);
  const [isFinishingLoading, setIsFinishingLoading] = useState(false);
  // Holds the function to execute once the loading bar hits 100%
  const [pendingUpdate, setPendingUpdate] = useState<(() => void) | null>(null);

  const [error, setError] = useState<string | null>(null);

  const [savedStories, setSavedStories] = useState<SavedStory[]>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEYS.SAVED_STORIES);
      if (saved) {
        let parsed = JSON.parse(saved);
        parsed = parsed.map((s: any) => ({
          ...s,
          style: s.style === "Bedtime Story" ? "Bedtime" : 
                 s.style === "Dialogue-heavy" ? "Dialogue" : s.style
        }));
        return parsed;
      }
      return [];
    } catch (e) {
      console.error("Failed to parse saved stories", e);
      return [];
    }
  });

  const [savedFlashCards, setSavedFlashCards] = useState<SavedFlashCard[]>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEYS.SAVED_FLASHCARDS);
      return saved ? JSON.parse(saved) : [];
    } catch (e) {
      console.error("Failed to parse saved flashcards", e);
      return [];
    }
  });

  const [currentStoryId, setCurrentStoryId] = useState<string>(() => crypto.randomUUID());

  const currentSuggestedTopics = useMemo(() => {
    return LEVEL_SPECIFIC_TOPICS[appLanguage]?.[level] || LEVEL_SPECIFIC_TOPICS["English"]?.["A1.1"] || [];
  }, [level, appLanguage]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEYS.APP_LANGUAGE, appLanguage);
    localStorage.setItem(STORAGE_KEYS.LANGUAGE, language);
    localStorage.setItem(STORAGE_KEYS.LEVEL, level);
    localStorage.setItem(STORAGE_KEYS.STYLE, storyStyle);
    localStorage.setItem(STORAGE_KEYS.THEME, theme);
    localStorage.setItem(STORAGE_KEYS.SHOW_QUIZ, JSON.stringify(showQuiz));
    localStorage.setItem(STORAGE_KEYS.SHOW_FLASHCARDS, JSON.stringify(showFlashCards));
  }, [appLanguage, language, level, storyStyle, theme, showQuiz, showFlashCards]);

  useEffect(() => {
    const root = window.document.documentElement;
    if (theme === 'dark') {
      root.classList.add('dark');
    } else {
      root.classList.remove('dark');
    }
  }, [theme]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEYS.SAVED_STORIES, JSON.stringify(savedStories));
  }, [savedStories]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEYS.SAVED_FLASHCARDS, JSON.stringify(savedFlashCards));
  }, [savedFlashCards]);

  useEffect(() => {
    if (savedStories.some(s => s.id === currentStoryId) && storyHistory.length > 0) {
      setSavedStories(prev => prev.map(s => 
        s.id === currentStoryId ? { ...s, history: storyHistory } : s
      ));
    }
  }, [storyHistory, currentStoryId]);

  const handleLoadingComplete = () => {
    if (pendingUpdate) {
      pendingUpdate();
    }
    setPendingUpdate(null);
    setIsFinishingLoading(false);
    setIsGenerating(false);
    setIsRewriting(false);
  };

  const handleGenerateNew = async () => {
    setIsGenerating(true);
    setIsRewriting(false);
    setIsFinishingLoading(false);
    setIsFocused(false);
    setError(null);
    setStoryHistory([]);
    setCurrentIndex(-1);

    setCurrentStoryId(crypto.randomUUID());

    try {
      const topic = storyDescription.trim() || (currentSuggestedTopics[0] || "A random adventure");
      const newStory = await generateStory(
        language, 
        level, 
        topic, 
        storyStyle, 
        appLanguage,
        showQuiz,
        showFlashCards
      );

      // Store the update action for later
      setPendingUpdate(() => () => {
        setStoryHistory([newStory]);
        setCurrentIndex(0);
        window.scrollTo({ top: 0, behavior: 'smooth' });
      });

      // Signal loading bar to finish
      setIsFinishingLoading(true);

    } catch (err: any) {
      setError(err.message || t.errorGenerating);
      setIsGenerating(false);
    }
  };

  const handleNextPage = async () => {
    if (currentIndex < storyHistory.length - 1) {
      setCurrentIndex(prev => prev + 1);
      return;
    }

    setIsGenerating(true);
    setError(null);
    try {
      const lastStory = storyHistory[storyHistory.length - 1];
      const nextPart = await generateStory(
        language, 
        level, 
        `Continuation of: ${lastStory.title}`, 
        storyStyle, 
        appLanguage, 
        showQuiz,
        showFlashCards,
        lastStory.content
      );
      setStoryHistory(prev => [...prev, nextPart]);
      setCurrentIndex(prev => prev + 1);
    } catch (err: any) {
      setError(err.message || t.errorGenerating);
    } finally {
      setIsGenerating(false);
    }
  };

  const handleLevelChange = async (newLevel: CEFRLevel) => {
    if (isGenerating || currentIndex < 0 || !storyHistory[currentIndex]) return;

    setLevel(newLevel);
    setIsGenerating(true);
    setIsRewriting(true);
    setIsFinishingLoading(false);
    setError(null);

    try {
      const currentStoryContent = storyHistory[currentIndex].content;
      const rewrittenStory = await generateStory(
        language,
        newLevel,
        storyDescription || "Rewritten Story", 
        storyStyle,
        appLanguage,
        showQuiz,
        showFlashCards,
        undefined, 
        currentStoryContent 
      );

      // Store update action
      setPendingUpdate(() => () => {
        setStoryHistory(prev => {
          const newHistory = [...prev];
          newHistory[currentIndex] = rewrittenStory;
          return newHistory;
        });
      });

      // Signal loading bar to finish
      setIsFinishingLoading(true);

    } catch (err: any) {
      setError(err.message || t.errorGenerating);
      setIsGenerating(false);
      setIsRewriting(false);
    }
  };

  const handlePrevPage = () => {
    if (currentIndex > 0) {
      setCurrentIndex(prev => prev - 1);
    }
  };

  const handleTopicClick = (topic: string) => {
    setStoryDescription((prev) => {
      const trimmed = prev.trim();
      if (!trimmed) return topic;
      const existing = trimmed.split(',').map(s => s.trim());
      if (existing.includes(topic)) return trimmed;
      return `${trimmed}, ${topic}`;
    });
  };

  const handleToggleBookmark = () => {
    if (savedStories.some(s => s.id === currentStoryId)) {
      setSavedStories(prev => prev.filter(s => s.id !== currentStoryId));
    } else {
      if (storyHistory.length === 0) return;

      const newSavedStory: SavedStory = {
        id: currentStoryId,
        createdAt: Date.now(),
        language,
        level,
        style: storyStyle,
        topic: storyDescription || currentSuggestedTopics[0],
        history: storyHistory,
        appLanguage
      };
      setSavedStories(prev => [newSavedStory, ...prev]);
    }
  };

  const handleFlashCardToggle = (word: string, translation: string, isSaved: boolean) => {
    const id = `${language}-${word}`; 

    if (isSaved) {
      setSavedFlashCards(prev => {
        if (prev.some(fc => fc.id === id)) return prev;
        return [{
          id,
          word,
          translation,
          language,
          createdAt: Date.now()
        }, ...prev];
      });
    } else {
      setSavedFlashCards(prev => prev.filter(fc => fc.id !== id));
    }
  };

  const handleDeleteSavedFlashCard = (id: string) => {
    setSavedFlashCards(prev => prev.filter(fc => fc.id !== id));
  };

  const handleLoadStory = (story: SavedStory) => {
    setLanguage(story.language);
    setLevel(story.level);
    setStoryStyle(story.style);
    setStoryDescription(story.topic);
    setStoryHistory(story.history);
    setCurrentStoryId(story.id);
    setCurrentIndex(story.history.length - 1);
    setError(null);
  };

  const handleDeleteSavedStory = (id: string) => {
    setSavedStories(prev => prev.filter(s => s.id !== id));
  };

  const currentStory = currentIndex >= 0 ? storyHistory[currentIndex] : null;
  const themeGradient = LANGUAGE_THEMES[language] || "from-indigo-500 to-purple-600";
  const isBookmarked = savedStories.some(s => s.id === currentStoryId);

  return (
    <div className="min-h-screen bg-[#F8FAFC] text-gray-900 font-sans dark:bg-[#0B1120] dark:text-gray-100 transition-colors duration-300 selection:bg-indigo-500/20">

      {/* App Header */}
      <header className={`sticky top-0 z-40 w-full transition-all duration-500 ease-in-out ${isFocused ? 'lg:-translate-y-full opacity-0 lg:opacity-0 pointer-events-none' : 'translate-y-0 opacity-100'}`}>
        {/* Glass Effect Background */}
        <div className="absolute inset-0 bg-white/70 backdrop-blur-xl border-b border-gray-200/50 dark:bg-[#0B1120]/70 dark:border-gray-800/50 support-[backdrop-filter]:bg-white/60" />

        <div className="relative mx-auto max-w-7xl px-4 py-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between">
            <div className="group flex items-center space-x-3 cursor-default">
              <div className="relative rounded-2xl bg-gradient-to-br from-indigo-500 to-indigo-600 p-2.5 text-white shadow-lg shadow-indigo-500/25 transition-all duration-300 group-hover:shadow-indigo-500/40 group-hover:scale-105">
                <BookMarked className="h-6 w-6" />
                <div className="absolute inset-0 rounded-2xl bg-white/20 opacity-0 transition-opacity duration-300 group-hover:opacity-100" />
              </div>
              <div className="flex flex-col">
                <h1 className="text-xl font-bold tracking-tight text-gray-900 dark:text-white leading-tight font-display">
                  {t.appTitle}
                </h1>
                <p className="hidden text-xs font-medium text-gray-500 dark:text-gray-400 sm:block">
                  {t.appSubtitle}
                </p>
              </div>
            </div>

            <div className="flex items-center gap-2">
              <button
                onClick={() => setIsFlashCardsOpen(true)}
                className="group relative rounded-xl p-2.5 text-gray-500 transition-all duration-300 hover:bg-white hover:text-indigo-600 hover:shadow-md hover:shadow-gray-200/50 dark:text-gray-400 dark:hover:bg-gray-800 dark:hover:text-indigo-400 dark:hover:shadow-none"
                title={t.savedFlashCards}
              >
                <SquareStack className="h-5 w-5 transition-transform duration-300 group-hover:scale-110 group-hover:-rotate-3" />
              </button>

              <button
                onClick={() => setIsLibraryOpen(true)}
                className="group relative rounded-xl p-2.5 text-gray-500 transition-all duration-300 hover:bg-white hover:text-indigo-600 hover:shadow-md hover:shadow-gray-200/50 dark:text-gray-400 dark:hover:bg-gray-800 dark:hover:text-indigo-400 dark:hover:shadow-none"
                title={t.savedStories}
              >
                <Library className="h-5 w-5 transition-transform duration-300 group-hover:scale-110 group-hover:-rotate-3" />
              </button>

              <div className="mx-2 h-6 w-px bg-gray-200 dark:bg-gray-800"></div>

              <button
                onClick={() => setIsSettingsOpen(true)}
                className="group relative rounded-xl p-2.5 text-gray-500 transition-all duration-300 hover:bg-white hover:text-indigo-600 hover:shadow-md hover:shadow-gray-200/50 dark:text-gray-400 dark:hover:bg-gray-800 dark:hover:text-indigo-400 dark:hover:shadow-none"
                title={t.settingsTitle}
              >
                <SettingsIcon className="h-5 w-5 transition-transform duration-300 group-hover:scale-110 group-hover:rotate-12" />
              </button>
            </div>
          </div>
        </div>
      </header>

      <main className={`mx-auto max-w-7xl px-4 py-8 sm:px-6 lg:px-8 transition-all duration-500 ease-[cubic-bezier(0.34,1.56,0.64,1)] ${isFocused ? 'pt-8' : ''}`}>
        <div className="grid grid-cols-1 gap-8 lg:grid-cols-12 relative items-start">

          {/* Sidebar - Controls */}
          <aside className={`transition-all duration-500 ease-[cubic-bezier(0.34,1.56,0.64,1)] ${isFocused ? 'hidden opacity-0 translate-x-[-20px]' : 'lg:col-span-4 xl:col-span-3 opacity-100 translate-x-0'}`}>
            <div className="sticky top-28 overflow-hidden rounded-3xl bg-white shadow-xl shadow-gray-200/50 ring-1 ring-gray-900/5 dark:bg-[#111827] dark:ring-gray-800 dark:shadow-none">
              <div className={`bg-gradient-to-r ${themeGradient} px-6 py-5 relative overflow-hidden`}>
                <div className="absolute inset-0 bg-white/10 opacity-50 backdrop-blur-3xl"></div>
                <h2 className="relative flex items-center text-lg font-bold text-white font-display">
                  <Sparkles className="mr-2 h-5 w-5" /> {t.storySettings}
                </h2>
              </div>

              <div className="p-6 space-y-6">
                <Selector<Language>
                  label={t.targetLanguage}
                  value={language}
                  options={LANGUAGES}
                  onChange={setLanguage}
                  getLabel={(opt) => languageLabels[opt]}
                  disabled={isGenerating}
                  icon={<Globe className="h-4 w-4 text-indigo-500" />}
                />

                <Selector<CEFRLevel>
                  label={t.languageLevel}
                  value={level}
                  options={LEVELS}
                  onChange={setLevel}
                  getLabel={(opt) => levelDescriptions[opt]}
                  disabled={isGenerating}
                  icon={<BarChart2 className="h-4 w-4 text-indigo-500" />}
                />

                <Selector<StoryStyle>
                  label={t.storyStyle}
                  value={storyStyle}
                  options={STORY_STYLES}
                  onChange={setStoryStyle}
                  getLabel={(opt) => storyStyleLabels[opt]}
                  disabled={isGenerating}
                  icon={<Feather className="h-4 w-4 text-indigo-500" />}
                />

                <div className="space-y-2.5">
                  <label className="text-sm font-bold text-gray-700 dark:text-gray-200 flex items-center gap-2">
                    <Tag className="h-4 w-4 text-indigo-500" />
                    {t.storyDescription}
                  </label>
                  <textarea
                    value={storyDescription}
                    onChange={(e) => setStoryDescription(e.target.value)}
                    placeholder={t.descPlaceholder}
                    rows={3}
                    disabled={isGenerating}
                    className="w-full rounded-2xl border-0 bg-gray-50 px-4 py-3 text-sm text-gray-900 shadow-inner ring-1 ring-gray-200 focus:bg-white focus:outline-none focus:ring-2 focus:ring-indigo-500 transition-all dark:bg-gray-800/50 dark:ring-gray-700 dark:text-white dark:focus:bg-gray-800 dark:focus:ring-indigo-500/50 resize-none placeholder:text-gray-400"
                  />
                </div>

                <div className="space-y-3">
                  <p className="text-xs font-bold uppercase tracking-wider text-gray-400 dark:text-gray-500">{t.suggestedTopics}</p>
                  <div className="flex flex-wrap gap-2">
                    {currentSuggestedTopics.map((topic) => (
                      <button
                        key={topic}
                        onClick={() => handleTopicClick(topic)}
                        disabled={isGenerating}
                        className="grow rounded-xl bg-gray-50 px-3 py-1.5 text-xs font-semibold text-gray-600 ring-1 ring-gray-200 hover:bg-indigo-50 hover:text-indigo-600 hover:ring-indigo-200 transition-all disabled:opacity-50 dark:bg-gray-800 dark:text-gray-300 dark:ring-gray-700 dark:hover:bg-indigo-900/30 dark:hover:text-indigo-300 dark:hover:ring-indigo-800"
                      >
                        {topic}
                      </button>
                    ))}
                  </div>
                </div>

                <button
                  onClick={handleGenerateNew}
                  disabled={isGenerating}
                  className="group flex w-full items-center justify-center space-x-2 rounded-2xl bg-indigo-600 px-4 py-3.5 font-bold text-white shadow-lg shadow-indigo-500/30 transition-all hover:bg-indigo-700 hover:scale-[1.02] hover:shadow-indigo-500/40 active:scale-[0.98] focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:ring-offset-2 disabled:opacity-70 disabled:cursor-not-allowed disabled:hover:scale-100 dark:shadow-none dark:hover:bg-indigo-500"
                >
                  <Send className="h-5 w-5 transition-transform group-hover:-translate-y-0.5 group-hover:translate-x-0.5" />
                  <span>{t.newStory}</span>
                </button>
              </div>
            </div>
          </aside>

          {/* Main Content - Story Display */}
          <section className={`transition-all duration-500 ${isFocused ? 'lg:col-span-12 max-w-5xl mx-auto' : 'lg:col-span-8 xl:col-span-9'}`}>
            {(isGenerating && (!currentStory || isRewriting)) ? (
              <div className="mt-8 lg:mt-12">
                <LoadingState 
                  message={isRewriting ? t.rewritingStory : t.startingStory} 
                  finish={isFinishingLoading}
                  onFinished={handleLoadingComplete}
                />
              </div>
            ) : error ? (
              <div className="rounded-2xl bg-red-50 p-6 text-sm text-red-700 ring-1 ring-red-200 dark:bg-red-900/20 dark:text-red-300 dark:ring-red-900/50 flex flex-col items-center text-center">
                 <span className="text-2xl mb-2">⚠️</span>
                 <p className="font-medium">{error}</p>
              </div>
            ) : currentStory ? (
              <StoryDisplay
                story={currentStory}
                language={languageLabels[language]}
                storyStyle={storyStyle}
                styleLabel={storyStyleLabels[storyStyle]}
                level={level}
                currentPage={currentIndex + 1}
                onNextPage={handleNextPage}
                onPrevPage={handlePrevPage}
                canGoPrev={currentIndex > 0}
                canGoNext={true}
                hasNextPageInHistory={currentIndex < storyHistory.length - 1}
                isGeneratingNext={isGenerating}
                translations={t}
                isBookmarked={isBookmarked}
                onToggleBookmark={handleToggleBookmark}
                isFocused={isFocused}
                onToggleFocus={() => setIsFocused(!isFocused)}
                showQuiz={showQuiz}
                showFlashCards={showFlashCards}
                onFlashCardToggle={handleFlashCardToggle}
                onLevelChange={handleLevelChange}
              />
            ) : (
              <div className="flex h-full min-h-[500px] flex-col items-center justify-center rounded-3xl border-2 border-dashed border-gray-200 bg-white/50 p-12 text-center dark:bg-gray-900/50 dark:border-gray-800">
                <div className="mb-6 rounded-3xl bg-white p-6 shadow-xl shadow-indigo-100 ring-1 ring-gray-100 dark:bg-gray-800 dark:shadow-none dark:ring-gray-700">
                  <div className="relative">
                     <div className="absolute inset-0 animate-ping rounded-full bg-indigo-400 opacity-20"></div>
                     <BookMarked className="h-12 w-12 text-indigo-600 dark:text-indigo-400 relative z-10" />
                  </div>
                </div>
                <h3 className="text-2xl font-bold text-gray-900 dark:text-white font-display tracking-tight">{t.readyToRead}</h3>
                <p className="mt-3 text-lg text-gray-500 dark:text-gray-400 max-w-sm mx-auto leading-relaxed">{t.readyPrompt}</p>
              </div>
            )}
          </section>
        </div>
      </main>

      <SettingsModal
        isOpen={isSettingsOpen}
        onClose={() => setIsSettingsOpen(false)}
        appLanguage={appLanguage}
        onLanguageChange={setAppLanguage}
        theme={theme}
        onThemeChange={setTheme}
        showQuiz={showQuiz}
        onShowQuizChange={setShowQuiz}
        showFlashCards={showFlashCards}
        onShowFlashCardsChange={setShowFlashCards}
        translations={t}
      />

      <SavedStoriesModal 
        isOpen={isLibraryOpen}
        onClose={() => setIsLibraryOpen(false)}
        savedStories={savedStories}
        onLoadStory={handleLoadStory}
        onDeleteStory={handleDeleteSavedStory}
        translations={t}
      />

      <SavedFlashCardsModal
        isOpen={isFlashCardsOpen}
        onClose={() => setIsFlashCardsOpen(false)}
        savedFlashCards={savedFlashCards}
        onDeleteFlashCard={handleDeleteSavedFlashCard}
        translations={t}
      />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { BookOpen, Languages, HelpCircle, CheckCircle2, XCircle, ArrowLeft, ArrowRight, Loader2, Bookmark, Maximize2, Minimize2, Sparkles, Layers, GraduationCap, ChevronDown } from 'lucide-react';
import { StoryResponse, StoryStyle, CEFRLevel } from '../types';
import { LEVELS } from '../constants';

interface StoryDisplayProps {
  story: StoryResponse;
  language: string;
  storyStyle: StoryStyle;
  styleLabel: string;
  level: string;
  onNextPage: () => void;
  onPrevPage: () => void;
  canGoPrev: boolean;
  canGoNext: boolean;
  hasNextPageInHistory: boolean;
  isGeneratingNext: boolean;
  currentPage: number;
  translations: Record<string, string>;
  isBookmarked: boolean;
  onToggleBookmark: () => void;
  isFocused: boolean;
  onToggleFocus: () => void;
  showQuiz: boolean;
  showFlashCards: boolean;
  onFlashCardToggle: (word: string, translation: string, isSaved: boolean) => void;
  onLevelChange: (level: CEFRLevel) => void;
}

interface TextSegment {
  type: 'text' | 'vocab';
  content: string;
  translation?: string;
  pre?: string;
  post?: string;
}

interface VocabItem {
  word: string;
  translation: string;
}

/**
 * Robustly parses text into segments and attaches orphan punctuation to the relevant vocab word.
 * This ensures that "word." or "(word)" wraps as a single unit.
 */
const parseParagraph = (text: string): TextSegment[] => {
  if (!text) return [];

  const regex = /\{([^{}|]+?)\s*\|\s*([^{}|]+?)\}/g;
  const rawSegments: TextSegment[] = [];
  let lastIndex = 0;
  let match;

  // 1. Initial Split
  while ((match = regex.exec(text)) !== null) {
    if (match.index > lastIndex) {
      rawSegments.push({
        type: 'text',
        content: text.slice(lastIndex, match.index)
      });
    }

    const word = match[1].trim();
    const translation = match[2].trim();

    if (word && translation) {
      rawSegments.push({
        type: 'vocab',
        content: word,
        translation: translation
      });
    } else {
      // Fallback for malformed tags
      rawSegments.push({
        type: 'text',
        content: match[0]
      });
    }

    lastIndex = regex.lastIndex;
  }

  if (lastIndex < text.length) {
    rawSegments.push({
      type: 'text',
      content: text.slice(lastIndex)
    });
  }

  // 2. Post-process to glue punctuation
  const PREFIX_RE = /([(\["'“‘«¿¡]+)$/;
  const SUFFIX_RE = /^([.,!?:;:)\]"'”’»]+)/;

  for (let i = 0; i < rawSegments.length; i++) {
    const segment = rawSegments[i];
    if (segment.type === 'vocab') {
      if (i > 0 && rawSegments[i - 1].type === 'text') {
        const prev = rawSegments[i - 1];
        const match = prev.content.match(PREFIX_RE);
        if (match) {
          const punctuation = match[1];
          segment.pre = (segment.pre || '') + punctuation;
          prev.content = prev.content.slice(0, -punctuation.length);
        }
      }

      if (i < rawSegments.length - 1 && rawSegments[i + 1].type === 'text') {
        const next = rawSegments[i + 1];
        const match = next.content.match(SUFFIX_RE);
        if (match) {
          const punctuation = match[1];
          segment.post = (segment.post || '') + punctuation;
          next.content = next.content.slice(punctuation.length);
        }
      }
    }
  }

  return rawSegments.filter(s => s.type === 'vocab' || s.content.length > 0);
};

/**
 * Returns accessible theme classes based on the story style.
 * Using "Lora" (serif) for story text to make it feel more book-like.
 */
const getThemeForStyle = (style: StoryStyle) => {
  // Base prose styles with better font stack and leading
  const baseProse = "prose-lg md:prose-xl leading-loose font-serif text-gray-800 dark:text-gray-200";
  const baseContainer = "w-full max-w-4xl mx-auto overflow-hidden rounded-3xl bg-white dark:bg-[#111827] shadow-2xl shadow-indigo-200/20 ring-1 ring-gray-900/5 dark:ring-gray-800 transition-all duration-500 ease-in-out";

  switch (style) {
    case "Adventure":
    case "Mystery":
    case "Thriller":
    case "History":
    case "Biography":
    case "Serious":
      return {
        container: `${baseContainer}`,
        headerBg: "bg-slate-900 dark:bg-black",
        prose: `${baseProse} prose-slate dark:prose-invert`
      };

    case "Bedtime":
    case "Romance":
    case "Fantasy":
      return {
        container: `${baseContainer}`,
        headerBg: "bg-indigo-900 dark:bg-indigo-950",
        prose: `${baseProse} prose-indigo dark:prose-invert`
      };

    case "News":
      return {
        container: `${baseContainer} font-sans`, // News usually Sans
        headerBg: "bg-gray-900 dark:bg-gray-950",
        prose: `prose-lg md:prose-xl leading-normal text-gray-800 dark:text-gray-200 prose-gray dark:prose-invert font-sans` 
      };

    case "Sci-Fi":
      return {
        container: `${baseContainer} font-sans`,
        headerBg: "bg-blue-900 dark:bg-blue-950",
        prose: `prose-lg md:prose-xl leading-loose text-gray-800 dark:text-gray-200 prose-blue dark:prose-invert font-sans`
      };

    case "Dialogue":
      return {
        container: `${baseContainer} font-sans`,
        headerBg: "bg-teal-800 dark:bg-teal-900",
        prose: `prose-lg md:prose-xl leading-loose text-gray-800 dark:text-gray-200 prose-teal dark:prose-invert font-sans space-y-6` 
      };

    case "Diary":
       return {
         container: `${baseContainer}`,
         headerBg: "bg-stone-700 dark:bg-stone-800",
         prose: `${baseProse} prose-stone dark:prose-invert italic`
       };

    default: // Standard, Funny
      return {
        container: `${baseContainer}`,
        headerBg: "bg-indigo-600 dark:bg-indigo-700",
        prose: `${baseProse} prose-indigo dark:prose-invert`
      };
  }
};

export const StoryDisplay: React.FC<StoryDisplayProps> = ({ 
  story, 
  language, 
  storyStyle,
  styleLabel, 
  level,
  onNextPage,
  onPrevPage,
  canGoPrev,
  canGoNext,
  hasNextPageInHistory,
  isGeneratingNext,
  currentPage,
  translations,
  isBookmarked,
  onToggleBookmark,
  isFocused,
  onToggleFocus,
  showQuiz,
  showFlashCards,
  onFlashCardToggle,
  onLevelChange
}) => {
  const [showTranslation, setShowTranslation] = useState(false);
  const [activeTooltipId, setActiveTooltipId] = useState<string | null>(null);
  const [quizAnswers, setQuizAnswers] = useState<Record<number, string>>({});
  const [activeTab, setActiveTab] = useState<'quiz' | 'flashcards'>('quiz');
  const [flippedCards, setFlippedCards] = useState<Set<number>>(new Set());

  // Default to the first available tab if one is disabled
  useEffect(() => {
    if (showQuiz && !showFlashCards) setActiveTab('quiz');
    else if (!showQuiz && showFlashCards) setActiveTab('flashcards');
    else if (showQuiz && showFlashCards && activeTab === 'quiz') setActiveTab('quiz'); // Preserve unless invalid
  }, [showQuiz, showFlashCards]);

  useEffect(() => {
    setShowTranslation(false);
    setActiveTooltipId(null);
    setQuizAnswers({});
    setFlippedCards(new Set());
    // If both are enabled, default back to quiz on new story load
    if (showQuiz) setActiveTab('quiz');
    else if (showFlashCards) setActiveTab('flashcards');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, [story]);

  const paragraphs = useMemo(() => {
    if (!story.content) return [];
    const normalizedContent = story.content.replace(/\\n/g, '\n');
    return normalizedContent.split(/\n+/).filter(p => p.trim().length > 0);
  }, [story.content]);

  // Extract all vocabulary for Flash Cards
  const vocabList = useMemo(() => {
    if (!story.content) return [];
    const regex = /\{([^{}|]+?)\s*\|\s*([^{}|]+?)\}/g;
    const list: VocabItem[] = [];
    let match;
    const seen = new Set<string>();

    while ((match = regex.exec(story.content)) !== null) {
      const word = match[1].trim();
      const translation = match[2].trim();
      if (word && translation && !seen.has(word)) {
        list.push({ word, translation });
        seen.add(word);
      }
    }
    return list;
  }, [story.content]);

  const handleBackgroundClick = () => {
    setActiveTooltipId(null);
  };

  const handleQuizOptionClick = (questionIndex: number, option: string) => {
    setQuizAnswers(prev => ({
      ...prev,
      [questionIndex]: option
    }));
  };

  const toggleCardFlip = (index: number) => {
    setFlippedCards(prev => {
      const newSet = new Set(prev);
      const isCurrentlyFlipped = newSet.has(index);

      if (isCurrentlyFlipped) {
        newSet.delete(index);
        // If removing flip, we call toggle with false (remove from saved)
        onFlashCardToggle(vocabList[index].word, vocabList[index].translation, false);
      } else {
        newSet.add(index);
        // If adding flip, we call toggle with true (add to saved)
        onFlashCardToggle(vocabList[index].word, vocabList[index].translation, true);
      }
      return newSet;
    });
  };

  const theme = getThemeForStyle(storyStyle);
  const hasTabs = showQuiz && showFlashCards;

  return (
    <div className={`animate-fade-in-up ${theme.container}`}>
      {/* Header */}
      <div className={`border-b border-white/10 px-6 py-5 text-white transition-colors duration-300 ${theme.headerBg} relative overflow-hidden`}>
        {/* Subtle noise/texture overlay for premium feel */}
        <div className="absolute inset-0 opacity-10 bg-[url('https://www.transparenttextures.com/patterns/stardust.png')]"></div>

        <div className="relative flex items-center justify-between z-10 font-sans">
          <div className="flex items-center space-x-3">
            <div className="p-2 rounded-xl bg-white/10 backdrop-blur-sm">
               <BookOpen className="h-5 w-5 opacity-90" />
            </div>
            <div className="flex flex-col">
              <span className="font-bold text-lg leading-tight tracking-tight">{language}</span>
              <span className="text-xs font-medium opacity-70 uppercase tracking-wider">{styleLabel}</span>
            </div>
          </div>
          <div className="flex items-center gap-4">
             <div className="flex items-center gap-3 bg-black/20 backdrop-blur-md rounded-full px-4 py-1.5 border border-white/10">
                <span className="opacity-90 text-xs font-bold uppercase tracking-wider">{translations.page} {currentPage}</span>
                <div className="h-3 w-px bg-white/20" />

                {/* Level Selector Badge */}
                <div className="relative group">
                  <span 
                    className="flex items-center gap-1 text-xs font-bold text-white cursor-pointer hover:text-indigo-200 transition-colors"
                    title="Change Level"
                  >
                      {level}
                      <ChevronDown className="h-3 w-3 opacity-80" />
                  </span>
                  <select
                    value={level}
                    onChange={(e) => onLevelChange(e.target.value as CEFRLevel)}
                    className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                    aria-label="Change Level"
                    disabled={isGeneratingNext}
                  >
                     {LEVELS.map(l => (
                       <option key={l} value={l} className="text-gray-900 bg-white dark:bg-gray-800 dark:text-gray-100">
                         {l}
                       </option>
                     ))}
                  </select>
                </div>
             </div>

             {/* Focus Toggle */}
             <button 
                onClick={onToggleFocus}
                className="p-2 rounded-full hover:bg-white/10 transition-colors focus:outline-none text-white/80 hover:text-white"
                title={isFocused ? "Exit Focus Mode" : "Enter Focus Mode"}
             >
                {isFocused ? <Minimize2 className="h-5 w-5" /> : <Maximize2 className="h-5 w-5" />}
             </button>
          </div>
        </div>
      </div>

      <div className="relative space-y-12 px-6 py-12 sm:px-16">

        {/* Bookmark Button */}
        <div className="absolute top-8 right-6 sm:right-10 z-10">
          <button 
            onClick={onToggleBookmark}
            className={`rounded-full p-3 transition-all duration-300 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:ring-offset-2 ${
              isBookmarked 
                ? "bg-amber-100 text-amber-600 shadow-amber-200 shadow-lg scale-110 hover:bg-amber-200 dark:bg-amber-900/50 dark:text-amber-400 dark:shadow-none" 
                : "bg-gray-50 text-gray-400 shadow-sm hover:bg-gray-100 hover:text-gray-600 hover:scale-105 dark:bg-gray-800 dark:text-gray-500 dark:hover:text-gray-300"
            }`}
            title={isBookmarked ? translations.bookmarked : translations.bookmarkStory}
          >
            <Bookmark className={`h-5 w-5 ${isBookmarked ? "fill-current" : ""}`} />
          </button>
        </div>

        {/* Story Section */}
        <section onClick={handleBackgroundClick} className="pt-2">
          <h2 className="mb-6 mr-12 text-3xl font-extrabold text-gray-900 dark:text-white sm:text-5xl text-center tracking-tight leading-tight font-display">
            {story.title}
          </h2>

          {story.shortDescription && (
            <p className="mb-10 text-center text-lg font-medium text-gray-500 dark:text-gray-400 max-w-2xl mx-auto font-sans leading-relaxed">
              {story.shortDescription}
            </p>
          )}

          <div className={`prose max-w-none ${theme.prose}`}>
            {paragraphs.map((paragraph, pIndex) => {
              const segments = parseParagraph(paragraph);

              return (
                <p key={pIndex} className="mb-8 last:mb-0 text-justify">
                  {segments.map((segment, sIndex) => {
                    if (segment.type === 'text') {
                      return <span key={sIndex}>{segment.content}</span>;
                    }

                    const uniqueId = `${pIndex}-${sIndex}`;
                    const isOpen = activeTooltipId === uniqueId;

                    return (
                      <span key={sIndex} className="relative inline-block group whitespace-nowrap">
                        {segment.pre && <span className="mr-[1px] opacity-90">{segment.pre}</span>}
                        <span
                          role="button"
                          tabIndex={0}
                          onClick={(e) => {
                            e.stopPropagation();
                            setActiveTooltipId(isOpen ? null : uniqueId);
                          }}
                          onKeyDown={(e) => {
                            if (e.key === 'Enter' || e.key === ' ') {
                              e.preventDefault();
                              e.stopPropagation();
                              setActiveTooltipId(isOpen ? null : uniqueId);
                            }
                          }}
                          className={`
                            cursor-pointer rounded-sm transition-all duration-200 outline-none px-[2px] mx-[1px]
                            ${isOpen 
                              ? 'bg-indigo-100 text-indigo-900 dark:bg-indigo-900 dark:text-indigo-100 font-semibold decoration-transparent' 
                              : 'decoration-indigo-300/60 dark:decoration-indigo-500/60 underline underline-offset-4 decoration-2 hover:decoration-indigo-500 hover:bg-indigo-50 dark:hover:bg-indigo-900/30'
                            }
                          `}
                        >
                          {segment.content}
                        </span>
                        {segment.post && <span>{segment.post}</span>}

                        {/* Tooltip */}
                        <div 
                           className={`absolute bottom-full left-1/2 mb-3 z-50 -translate-x-1/2 transition-all duration-200 ease-out origin-bottom ${
                             isOpen ? 'opacity-100 scale-100 translate-y-0' : 'opacity-0 scale-95 translate-y-2 pointer-events-none'
                           }`}
                        >
                            <div className="relative rounded-2xl bg-[#0B1120] px-5 py-3 text-base font-semibold text-white shadow-2xl whitespace-nowrap dark:bg-white dark:text-gray-900 font-sans">
                              {segment.translation}
                              <div className="absolute top-full left-1/2 -ml-2 -mt-1 h-4 w-4 -translate-x-1/2 rotate-45 bg-[#0B1120] dark:bg-white"></div>
                            </div>
                        </div>
                      </span>
                    );
                  })}
                </p>
              );
            })}
          </div>
        </section>

        {/* Grammar Note */}
        {story.grammarPoint && (
          <div className="mt-12 rounded-2xl border-0 bg-gradient-to-br from-indigo-50 to-white p-6 shadow-sm ring-1 ring-indigo-100 dark:from-indigo-900/20 dark:to-gray-800 dark:ring-indigo-900/30 font-sans">
            <div className="flex items-start space-x-4">
              <div className="rounded-xl bg-indigo-100 p-2.5 dark:bg-indigo-900/40 shrink-0">
                <GraduationCap className="h-6 w-6 text-indigo-600 dark:text-indigo-400" />
              </div>
              <div>
                <h3 className="text-xs font-bold uppercase tracking-widest text-indigo-900 dark:text-indigo-300 mb-2">
                  {translations.grammarPoint}
                </h3>
                <p className="text-gray-700 dark:text-gray-300 text-lg leading-relaxed font-medium">
                  {story.grammarPoint}
                </p>
              </div>
            </div>
          </div>
        )}

        {/* Pagination Controls */}
        <div className="flex items-center justify-between pt-8 font-sans">
            <button
                onClick={onPrevPage}
                disabled={!canGoPrev || isGeneratingNext}
                className="group flex items-center space-x-2 rounded-2xl border-0 bg-gray-100 px-6 py-3.5 text-sm font-bold text-gray-600 transition-all hover:bg-gray-200 hover:text-indigo-600 disabled:opacity-50 disabled:cursor-not-allowed dark:bg-gray-800 dark:text-gray-400 dark:hover:bg-gray-700"
            >
                <ArrowLeft className="h-4 w-4 transition-transform group-hover:-translate-x-1" />
                <span>{translations.previousPage}</span>
            </button>

            <button
                onClick={onNextPage}
                disabled={!canGoNext || isGeneratingNext}
                className={`group flex items-center space-x-2 rounded-2xl px-8 py-3.5 text-sm font-bold shadow-lg transition-all active:scale-95 disabled:opacity-70 disabled:cursor-not-allowed disabled:active:scale-100
                    ${!hasNextPageInHistory 
                        ? "bg-indigo-600 text-white hover:bg-indigo-700 hover:shadow-indigo-500/30 shadow-indigo-500/20 dark:bg-indigo-500 dark:hover:bg-indigo-600" 
                        : "bg-white text-gray-700 ring-1 ring-gray-200 hover:bg-gray-50 hover:text-indigo-600 dark:bg-gray-800 dark:text-gray-300 dark:ring-gray-700 dark:hover:bg-gray-700"
                    }
                `}
            >
                {isGeneratingNext ? (
                     <>
                        <Loader2 className="h-4 w-4 animate-spin" />
                        <span>{translations.creatingNextPage}</span>
                     </>
                ) : (
                    <>
                        <span>{translations.nextPage}</span>
                        <ArrowRight className="h-4 w-4 transition-transform group-hover:translate-x-1" />
                    </>
                )}
            </button>
        </div>

        <div className="flex justify-center pt-4 font-sans">
            <button 
                onClick={() => setShowTranslation(!showTranslation)}
                className="flex items-center space-x-2 text-sm font-bold text-indigo-600 hover:text-indigo-800 dark:text-indigo-400 dark:hover:text-indigo-300 focus:outline-none transition-colors rounded-full py-2 px-4 hover:bg-indigo-50 dark:hover:bg-indigo-900/20"
            >
                <Languages className="h-4 w-4" />
                <span>{showTranslation ? translations.hideTranslation : translations.showTranslation}</span>
            </button>
        </div>

        {showTranslation && (
            <div className="animate-fade-in rounded-3xl bg-gray-50 p-8 text-gray-700 ring-1 ring-gray-900/5 dark:bg-gray-800 dark:text-gray-300 dark:ring-white/5 shadow-inner">
                <h3 className="mb-4 text-xs font-bold uppercase tracking-widest text-gray-400 dark:text-gray-500">{translations.translationTitle}</h3>
                <p className="whitespace-pre-line leading-relaxed text-lg font-serif">{story.englishTranslation}</p>
            </div>
        )}

        {/* Tabbed Interface for Quiz/Flash Cards */}
        {(showQuiz || showFlashCards) && (
            <div className="mt-12 border-t border-gray-100 dark:border-gray-800 pt-10 font-sans">

                {/* Tabs */}
                {hasTabs && (
                    <div className="flex space-x-8 border-b border-gray-200 dark:border-gray-700 mb-10">
                        <button
                            onClick={() => setActiveTab('quiz')}
                            className={`pb-4 text-sm font-bold uppercase tracking-wide transition-all border-b-[3px] ${
                                activeTab === 'quiz' 
                                    ? 'border-indigo-600 text-indigo-600 dark:border-indigo-400 dark:text-indigo-400' 
                                    : 'border-transparent text-gray-400 hover:text-gray-600 dark:text-gray-500 dark:hover:text-gray-300'
                            }`}
                        >
                            <div className="flex items-center gap-2">
                                <HelpCircle className="h-4 w-4" />
                                {translations.comprehensionQuiz}
                            </div>
                        </button>
                        <button
                            onClick={() => setActiveTab('flashcards')}
                            className={`pb-4 text-sm font-bold uppercase tracking-wide transition-all border-b-[3px] ${
                                activeTab === 'flashcards' 
                                    ? 'border-indigo-600 text-indigo-600 dark:border-indigo-400 dark:text-indigo-400' 
                                    : 'border-transparent text-gray-400 hover:text-gray-600 dark:text-gray-500 dark:hover:text-gray-300'
                            }`}
                        >
                             <div className="flex items-center gap-2">
                                <Layers className="h-4 w-4" />
                                {translations.flashCards}
                             </div>
                        </button>
                    </div>
                )}

                {/* Single Title if no tabs */}
                {!hasTabs && (
                    <div className="flex items-center space-x-3 mb-10">
                         <div className="rounded-xl bg-indigo-100 p-2.5 dark:bg-indigo-900/30">
                            {showQuiz ? <HelpCircle className="h-6 w-6 text-indigo-600 dark:text-indigo-400" /> : <Layers className="h-6 w-6 text-indigo-600 dark:text-indigo-400" />}
                         </div>
                         <h3 className="text-xl font-bold text-gray-900 dark:text-white">
                             {showQuiz ? translations.comprehensionQuiz : translations.flashCards}
                         </h3>
                    </div>
                )}

                {/* Quiz Content */}
                {showQuiz && activeTab === 'quiz' && (
                    <div className="space-y-6 animate-fade-in">
                        {story.quiz.map((item, index) => {
                            const selectedAnswer = quizAnswers[index];
                            const isCorrect = selectedAnswer === item.correctAnswer;
                            const hasAnswered = selectedAnswer != null;

                            return (
                            <div key={index} className="group relative rounded-3xl border border-gray-100 bg-white p-8 transition-all duration-300 hover:shadow-xl hover:shadow-gray-200/50 hover:border-gray-200 dark:border-gray-800 dark:bg-[#151d30] dark:hover:border-gray-700 dark:hover:shadow-none overflow-hidden">
                                <p className="mb-6 text-xl font-semibold text-gray-900 dark:text-gray-100 leading-snug">
                                <span className="mr-4 inline-flex items-center justify-center rounded-lg bg-indigo-50 px-2.5 py-1 text-sm font-bold text-indigo-600 ring-1 ring-indigo-500/10 dark:bg-indigo-900/30 dark:text-indigo-400 dark:ring-indigo-500/20">{index + 1}</span>
                                {item.question}
                                </p>

                                <div className="space-y-3">
                                {item.options.map((option) => {
                                    let buttonStyle = "border-gray-100 bg-gray-50 text-gray-700 hover:bg-indigo-50 hover:text-indigo-700 hover:border-indigo-200 dark:border-gray-700 dark:bg-gray-800 dark:text-gray-300 dark:hover:bg-indigo-900/20 dark:hover:text-indigo-300 dark:hover:border-indigo-800";
                                    let icon = null;

                                    const isSelected = selectedAnswer === option;
                                    const isCorrectOption = option === item.correctAnswer;

                                    if (hasAnswered) {
                                    if (isCorrectOption) {
                                        buttonStyle = "border-green-500 bg-green-50 text-green-900 font-bold ring-1 ring-green-500 dark:bg-green-900/20 dark:text-green-300 dark:border-green-500/50";
                                        icon = <CheckCircle2 className="h-5 w-5 text-green-600 dark:text-green-400 animate-scale-in" />;
                                    } else if (isSelected) {
                                        buttonStyle = "border-red-300 bg-red-50 text-red-900 dark:bg-red-900/20 dark:text-red-300 dark:border-red-500/50";
                                        icon = <XCircle className="h-5 w-5 text-red-500 dark:text-red-400 animate-scale-in" />;
                                    } else {
                                        buttonStyle = "border-gray-100 bg-gray-50 text-gray-400 opacity-50 dark:border-gray-800 dark:bg-gray-900/50 dark:text-gray-600";
                                    }
                                    }

                                    return (
                                    <button
                                        key={option}
                                        onClick={() => !hasAnswered && handleQuizOptionClick(index, option)}
                                        disabled={hasAnswered}
                                        className={`flex w-full items-center justify-between rounded-2xl border px-6 py-4 text-left text-base font-medium transition-all duration-200 ${buttonStyle} ${!hasAnswered ? "active:scale-[0.99]" : ""}`}
                                    >
                                        <span>{option}</span>
                                        {icon}
                                    </button>
                                    );
                                })}
                                </div>

                                {hasAnswered && (
