import { GoogleGenAI, Type, Schema } from "@google/genai";
import { CEFRLevel, Language, StoryResponse, StoryStyle, AppLanguage } from "../types";

const getVocabCount = (level: CEFRLevel): string => {
  if (level.startsWith("A1")) return "25-35"; 
  if (level.startsWith("A2")) return "20-28";
  if (level.startsWith("B1")) return "18-24";
  if (level.startsWith("B2")) return "15-20";
  return "12-18"; 
};

/**
 * Returns style-specific prompt instructions and temperature.
 * Adjusts constraints based on CEFR level to ensure accessibility.
 */
const getStyleConfig = (style: StoryStyle, level: CEFRLevel): { instructions: string; temperature: number } => {
  const isBeginner = level.startsWith("A1") || level === "A2.1";

  switch (style) {
    case "Adventure":
      return {
        instructions: `GENRE: ADVENTURE. 
        - Focus on action, travel, and discovery.
        - ${isBeginner ? "Keep the plot linear. Simple 'Problem -> Journey -> Solution' structure." : "Include suspense, diverse locations, and unexpected obstacles."}`,
        temperature: 0.6
      };
    case "Bedtime":
      return {
        instructions: `GENRE: BEDTIME STORY.
        - Tone: Soothing, calm, repetitive, and gentle.
        - Structure: Begin with "Once upon a time" (or language equivalent) and end happily.
        - ${isBeginner ? "Use heavy repetition of key vocabulary for reinforcement." : "Use descriptive, dream-like imagery."}`,
        temperature: 0.4
      };
    case "Biography":
      return {
        instructions: `GENRE: BIOGRAPHY.
        - Format: Factual account of a person's life (real or fictional).
        - Tone: Respectful, informative, chronological.
        - ${isBeginner ? "Focus on basic life events: birth, school, job, family." : "Discuss achievements, historical context, and legacy."}`,
        temperature: 0.3
      };
    case "Dialogue":
      return {
        instructions: `GENRE: DIALOGUE / SCRIPT.
        - Format: Use a script format (e.g., 'Person A: [Text]').
        - Focus: Spoken language, natural conversational fillers appropriate for ${level}.
        - ${isBeginner ? "Topics: Greetings, ordering food, asking directions." : "Topics: Debates, expressing complex opinions, negotiating."}`,
        temperature: 0.5
      };
    case "Diary":
      return {
        instructions: `GENRE: DIARY ENTRY.
        - Format: Start with a date or 'Dear Diary'. First-person perspective ('I').
        - Tone: Personal, reflective, informal.
        - ${isBeginner ? "Describe daily routine, weather, and basic feelings." : "Express deep thoughts, regrets, hopes, and complex emotions."}`,
        temperature: 0.5
      };
    case "Fantasy":
      return {
        instructions: `GENRE: FANTASY.
        - Elements: Magic, mythical creatures, imaginary worlds.
        - ${isBeginner ? "Keep magic simple (e.g., a flying cat, a magic stone). Avoid complex lore." : "Build a rich world. Use descriptive adjectives for settings."}`,
        temperature: 0.7
      };
    case "Funny":
      return {
        instructions: `GENRE: COMEDY / FUNNY.
        - Goal: Make the reader laugh using situational humor.
        - ${isBeginner ? "Use physical comedy or simple misunderstandings. NO puns or wordplay (too hard)." : "Use wit, irony, and sarcasm."}`,
        temperature: 0.8
      };
    case "History":
      return {
        instructions: `GENRE: HISTORICAL FICTION / HISTORY.
        - Setting: A specific time in the past.
        - ${isBeginner ? "Focus on a single event or day. Use simple Past Simple sentences." : "Describe the era, costumes, and social atmosphere."}`,
        temperature: 0.3
      };
    case "Mystery":
      return {
        instructions: `GENRE: MYSTERY.
        - Plot: A puzzle, missing object, or strange event needs solving.
        - ${isBeginner ? "The solution should be obvious and physical (e.g., the dog hid the keys)." : "Include red herrings and subtle clues."}`,
        temperature: 0.6
      };
    case "News":
      return {
        instructions: `GENRE: NEWS ARTICLE.
        - Format: Headline at the top. Third-person 'Reporter' voice.
        - Tone: Objective, factual, formal.
        - ${isBeginner ? "Short sentences. 'Who, What, Where'. Simple reported speech." : "Use passive voice. 'It was reported that...'. Interview quotes."}`,
        temperature: 0.2
      };
    case "Romance":
      return {
        instructions: `GENRE: ROMANCE.
        - Focus: Relationships, feelings, dates.
        - Tone: Warm, emotional.
        - ${isBeginner ? "Focus on first meeting, liking someone, going to the movies." : "Focus on deep connection, relationship struggles, and resolution."}`,
        temperature: 0.6
      };
    case "Sci-Fi":
      return {
        instructions: `GENRE: SCIENCE FICTION.
        - Elements: Robots, space, future technology.
        - ${isBeginner ? "Focus on everyday life with a robot helper. Simple gadgets." : "Explore themes of AI, space travel, or ethical dilemmas."}`,
        temperature: 0.7
      };
    case "Serious":
      return {
        instructions: `GENRE: SERIOUS / DRAMA.
        - Tone: Grounded, realistic, perhaps slightly melancholic or focused on important issues.
        - ${isBeginner ? "A serious day at work or a lost pet." : "Social issues, personal loss, or difficult decisions."}`,
        temperature: 0.4
      };
    case "Thriller":
      return {
        instructions: `GENRE: THRILLER.
        - Tone: Tense, urgent, fast-paced.
        - ${isBeginner ? "Someone is late, running for a bus, or hearing a strange noise." : "High stakes, racing against time, psychological tension."}`,
        temperature: 0.7
      };
    default: // Standard
      return {
        instructions: "GENRE: STANDARD STORY. A balanced, engaging narrative suitable for general reading practice.",
        temperature: 0.5
      };
  }
};

/**
 * Enhanced Level Constraints with FORBIDDEN GRAMMAR to prevent level-bleed.
 */
const getLevelConstraints = (level: CEFRLevel): string => {
  switch (level) {
    case "A1.1":
      return `
        LEVEL: A1.1 (BREAKTHROUGH)
        - POSITIVE: Top 100 nouns only. Present Simple 'be' and 'have'.
        - FORBIDDEN: NO 'but', NO 'because', NO Past tenses, NO Future tenses, NO adjectives (except colors/size).
      `;
    case "A1.2":
      return `
        LEVEL: A1.2 (BEGINNER)
        - POSITIVE: Basic Present Simple. 'and', 'or'.
        - FORBIDDEN: NO Past Continuous, NO Perfect tenses, NO 'if' clauses, NO 'when' clauses.
      `;
    case "A1.3":
      return `
        LEVEL: A1.3 (ELEMENTARY)
        - POSITIVE: Past Simple (Regular verbs), Present Continuous. 'because'.
        - FORBIDDEN: NO Passive voice, NO Conditional moods, NO Irregular past forms if obscure.
      `;
    case "A2.1":
      return `
        LEVEL: A2.1 (HIGH ELEMENTARY)
        - POSITIVE: Future 'will', basic Comparatives.
        - FORBIDDEN: NO Present Perfect, NO Modal verbs like 'should' or 'must'.
      `;
    case "A2.2":
      return `
        LEVEL: A2.2 (PRE-INTERMEDIATE)
        - POSITIVE: Present Perfect, Modal verbs, First Conditional.
        - FORBIDDEN: NO Past Perfect, NO Third Conditional, NO Passive Voice.
      `;
    case "B1.1":
      return `
        LEVEL: B1.1 (INTERMEDIATE)
        - POSITIVE: Simple Passive Voice, Second Conditional.
        - FORBIDDEN: NO Future Perfect, NO Subjunctive Mood, NO Inversion.
      `;
    case "B1.2":
      return `
        LEVEL: B1.2 (HIGH INTERMEDIATE)
        - POSITIVE: Past Perfect, Reported Speech, 'although'.
        - FORBIDDEN: NO Mixed Conditionals, NO complex Gerund vs Infinitive nuances.
      `;
    case "B2.1":
      return `
        LEVEL: B2.1 (UPPER INTERMEDIATE)
        - POSITIVE: Future Continuous, Mixed Conditionals.
        - FORBIDDEN: NO Archaic vocabulary, NO overly formal academic structures.
      `;
    default:
      return "Ensure natural use of the language appropriate for the selected CEFR level.";
  }
};

/**
 * Helper to sanitise JSON response from the model, stripping Markdown fences if present.
 */
const cleanJsonResponse = (text: string): string => {
  let cleaned = text.trim();
  if (cleaned.startsWith('```json')) {
    cleaned = cleaned.replace(/^```json/, '').replace(/```$/, '');
  } else if (cleaned.startsWith('```')) {
    cleaned = cleaned.replace(/^```/, '').replace(/```$/, '');
  }
  return cleaned.trim();
};

export const generateStory = async (
  language: Language,
  level: CEFRLevel,
  topic: string,
  style: StoryStyle,
  outputLanguage: AppLanguage,
  enableQuiz: boolean,
  enableFlashCards: boolean,
  previousContext?: string,
  contentToRewrite?: string
): Promise<StoryResponse> => {

  // Create a new instance right before use to ensure latest API_KEY is used.
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const vocabCount = getVocabCount(level);
  const strictLevelConstraints = getLevelConstraints(level);
  const styleConfig = getStyleConfig(style, level);

  // Dynamic Schema Construction
  const schemaProperties: any = {
    title: {
      type: Type.STRING,
      description: "The title of the story in the target language."
    },
    shortDescription: {
      type: Type.STRING,
      description: "A 1-sentence summary of the story in the user's interface language (English, Finnish, or Vietnamese)."
    },
    content: {
      type: Type.STRING,
      description: enableFlashCards 
        ? "The main body of the story in the target language. Use {word|translation} for highlights. MUST contain multiple paragraphs separated by newlines."
        : "The main body of the story in the target language. Do NOT use {word|translation} tags. Plain text only. MUST contain multiple paragraphs separated by newlines."
    },
    englishTranslation: {
      type: Type.STRING,
      description: "A full translation of the story in the user's interface language."
    },
    grammarPoint: {
      type: Type.STRING,
      description: "A short explanation of a specific grammar rule or structure used in the story, written in the user's interface language."
    }
  };

  const requiredFields = ["title", "shortDescription", "content", "englishTranslation", "grammarPoint"];

  if (enableQuiz) {
    schemaProperties.quiz = {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          question: { type: Type.STRING },
          options: { type: Type.ARRAY, items: { type: Type.STRING } },
          correctAnswer: { type: Type.STRING },
          explanation: { type: Type.STRING, description: "Explanation of why the answer is correct, in the user's interface language." }
        },
        required: ["question", "options", "correctAnswer", "explanation"]
      }
    };
    requiredFields.push("quiz");
  }

  if (enableFlashCards) {
    schemaProperties.vocabularyMetadata = {
      type: Type.OBJECT,
      description: "A mapping of every highlighted {word} to its verified CEFR level and reason for selection.",
      properties: {
        word: {
           type: Type.OBJECT,
           properties: {
             level: { type: Type.STRING },
             reason: { type: Type.STRING }
           }
        }
      },
      additionalProperties: {
        type: Type.OBJECT,
        properties: {
          level: { type: Type.STRING },
          reason: { type: Type.STRING }
        }
      }
    };
    requiredFields.push("vocabularyMetadata");
  }

  const responseSchema: Schema = {
    type: Type.OBJECT,
    properties: schemaProperties,
    required: requiredFields
  };

  // Determine the task prompt: Create new OR Rewrite existing
  const taskInstructions = contentToRewrite 
    ? `TASK: REWRITE the provided story content to be EXACTLY level ${level}.
       - Maintain the original plot, characters, and meaning.
       - Adjust vocabulary and grammar to match ${level}.
       - ORIGINAL CONTENT: "${contentToRewrite}"`
    : `TASK: Generate a ${language} story at EXACTLY level ${level}.
       ${previousContext ? `CONTEXT: This is a continuation of the previous part: "${previousContext}"` : ""}
       DRAFTING: Create a story about "${topic}" in ${language}.`;

  const prompt = `
    Role: Senior Language Education Specialist & CEFR Auditor.

    ${taskInstructions}

    SYSTEMIC WORKFLOW:
    1. CONFIGURATION: Use the following style settings:
       ${styleConfig.instructions}
    2. LENGTH & STRUCTURE (STRICT):
       - The story MUST be at least 3 distinct paragraphs long.
       - The total length MUST be approximately 200-300 words (or appropriate length for ${level} to allow for 3 paragraphs).
       - This is a strict requirement. Do not generate a single block of text. Use \\n\\n to separate paragraphs.
    3. AUDITING (CRITICAL): Scan the draft for grammar or vocabulary that is too complex for ${level}. Even if the style requires creativity, accessibility and level-adherence are the PRIORITY.
    4. REFINING: Rewrite any sentences that violate the ${level} constraints, even if it makes the style less "pure".
    5. PEDAGOGICAL METADATA:
       - Create a "shortDescription" in ${outputLanguage} that summarizes the story in 1 sentence to prime the learner.
       - Identify one key "grammarPoint" used in the story (e.g., "Use of Past Simple") and explain it simply in ${outputLanguage}.
       ${enableQuiz ? `- Create quiz explanations in ${outputLanguage}.` : ""}
    ${enableFlashCards ? `6. HIGHLIGHTING: Select ${vocabCount} vocabulary words that are appropriate and challenging for level ${level}. Use {word|translation} format in the content.` : "6. HIGHLIGHTING: Do NOT highlight any words. Provide plain text only."}

    CONSTRAINTS FOR ${level}:
    ${strictLevelConstraints}

    ${enableFlashCards ? `VOCABULARY METADATA RULES:
    - For every highlighted {word|translation}, you MUST categorize its CEFR difficulty in the "vocabularyMetadata" object.
    - Example: "vocabularyMetadata": { "exploration": { "level": "B2", "reason": "Academic abstract noun" } }` : ""}

    FORMAT:
    - Return JSON matching the schema.
    - Content must be in ${language}.
    - englishTranslation must be in ${outputLanguage}.
    - shortDescription must be in ${outputLanguage}.
    - grammarPoint must be in ${outputLanguage}.
    ${enableQuiz ? `- quiz questions must be in ${language}, but explanations must be in ${outputLanguage}.` : ""}
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview", 
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        temperature: styleConfig.temperature,
        thinkingConfig: { thinkingBudget: 4000 }
      }
    });

    const text = response.text;
    if (!text) throw new Error("Generation failed: No response text");

    const cleanedText = cleanJsonResponse(text);
    const parsed = JSON.parse(cleanedText);

    // Fill defaults if disabled to match StoryResponse type
    if (!enableQuiz) parsed.quiz = [];
    if (!enableFlashCards) parsed.vocabularyMetadata = {};

    return parsed as StoryResponse;
  } catch (error) {
    console.error("API Error:", error);
    throw new Error("Could not generate story. Please try again.");
  }
};

import React, { useState, useEffect, useMemo } from 'react';
import { BookMarked, Sparkles, Send, Tag, Settings as SettingsIcon, Library, Globe, BarChart2, Feather, SquareStack } from 'lucide-react';
import { LANGUAGES, LEVELS, LEVEL_SPECIFIC_TOPICS, STORY_STYLES, LEVEL_DESCRIPTIONS, STORY_STYLE_LABELS, APP_LANGUAGES, LANGUAGE_LABELS, LANGUAGE_THEMES } from './constants';
import { Language, CEFRLevel, GenerationState, StoryStyle, StoryResponse, AppLanguage, SavedStory, Theme, SavedFlashCard } from './types';
import { Selector } from './components/Selector';
import { StoryDisplay } from './components/StoryDisplay';
import { LoadingState } from './components/LoadingState';
import { SettingsModal } from './components/SettingsModal';
import { SavedStoriesModal } from './components/SavedStoriesModal';
import { SavedFlashCardsModal } from './components/SavedFlashCardsModal';
import { generateStory } from './services/geminiService';
import { TRANSLATIONS } from './translations';

const STORAGE_KEYS = {
  LANGUAGE: 'linguatale_pref_language',
  LEVEL: 'linguatale_pref_level',
  STYLE: 'linguatale_pref_style',
  APP_LANGUAGE: 'linguatale_app_language',
  SAVED_STORIES: 'linguatale_saved_stories',
  SAVED_FLASHCARDS: 'linguatale_saved_flashcards',
  THEME: 'linguatale_theme',
  SHOW_QUIZ: 'linguatale_show_quiz',
  SHOW_FLASHCARDS: 'linguatale_show_flashcards'
};

const generateId = () => {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) {
    return crypto.randomUUID();
  }
  return Date.now().toString(36) + Math.random().toString(36).substr(2);
};

const App: React.FC = () => {
  const [appLanguage, setAppLanguage] = useState<AppLanguage>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.APP_LANGUAGE);
    return (saved && APP_LANGUAGES.includes(saved as AppLanguage)) ? (saved as AppLanguage) : "English";
  });

  const [theme, setTheme] = useState<Theme>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.THEME);
    if (saved === 'dark' || saved === 'light') return saved;
    return 'light';
  });

  const [showQuiz, setShowQuiz] = useState<boolean>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.SHOW_QUIZ);
    return saved !== null ? JSON.parse(saved) : true;
  });

  const [showFlashCards, setShowFlashCards] = useState<boolean>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.SHOW_FLASHCARDS);
    return saved !== null ? JSON.parse(saved) : true;
  });

  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isLibraryOpen, setIsLibraryOpen] = useState(false);
  const [isFlashCardsOpen, setIsFlashCardsOpen] = useState(false);

  // Immersive Focus Mode State
  const [isFocused, setIsFocused] = useState(false);

  const t = TRANSLATIONS[appLanguage] || TRANSLATIONS["English"];
  const levelDescriptions = LEVEL_DESCRIPTIONS[appLanguage] || LEVEL_DESCRIPTIONS["English"];
  const storyStyleLabels = STORY_STYLE_LABELS[appLanguage] || STORY_STYLE_LABELS["English"];
  const languageLabels = LANGUAGE_LABELS[appLanguage] || LANGUAGE_LABELS["English"];

  const [language, setLanguage] = useState<Language>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.LANGUAGE);
    return (saved && LANGUAGES.includes(saved as Language)) ? (saved as Language) : "English";
  });

  const [level, setLevel] = useState<CEFRLevel>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.LEVEL);
    return (saved && LEVELS.includes(saved as CEFRLevel)) ? (saved as CEFRLevel) : "A1.1";
  });

  const [storyStyle, setStoryStyle] = useState<StoryStyle>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.STYLE);
    return (saved && STORY_STYLES.includes(saved as StoryStyle)) ? (saved as StoryStyle) : "Standard";
  });

  const [storyDescription, setStoryDescription] = useState<string>("");

  const [storyHistory, setStoryHistory] = useState<StoryResponse[]>([]);
  const [currentIndex, setCurrentIndex] = useState(-1);

  const [isGenerating, setIsGenerating] = useState(false);
  const [isRewriting, setIsRewriting] = useState(false);
  const [isFinishingLoading, setIsFinishingLoading] = useState(false);
  // Holds the function to execute once the loading bar hits 100%
  const [pendingUpdate, setPendingUpdate] = useState<(() => void) | null>(null);

  const [error, setError] = useState<string | null>(null);

  const [savedStories, setSavedStories] = useState<SavedStory[]>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEYS.SAVED_STORIES);
      if (saved) {
        let parsed = JSON.parse(saved);
        parsed = parsed.map((s: any) => ({
          ...s,
          style: s.style === "Bedtime Story" ? "Bedtime" : 
                 s.style === "Dialogue-heavy" ? "Dialogue" : s.style
        }));
        return parsed;
      }
      return [];
    } catch (e) {
      console.error("Failed to parse saved stories", e);
      return [];
    }
  });

  const [savedFlashCards, setSavedFlashCards] = useState<SavedFlashCard[]>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEYS.SAVED_FLASHCARDS);
      return saved ? JSON.parse(saved) : [];
    } catch (e) {
      console.error("Failed to parse saved flashcards", e);
      return [];
    }
  });

  const [currentStoryId, setCurrentStoryId] = useState<string>(generateId);

  const currentSuggestedTopics = useMemo(() => {
    return LEVEL_SPECIFIC_TOPICS[appLanguage]?.[level] || LEVEL_SPECIFIC_TOPICS["English"]?.["A1.1"] || [];
  }, [level, appLanguage]);

  // Combined Storage Effect
  useEffect(() => {
    localStorage.setItem(STORAGE_KEYS.APP_LANGUAGE, appLanguage);
    localStorage.setItem(STORAGE_KEYS.LANGUAGE, language);
    localStorage.setItem(STORAGE_KEYS.LEVEL, level);
    localStorage.setItem(STORAGE_KEYS.STYLE, storyStyle);
    localStorage.setItem(STORAGE_KEYS.THEME, theme);
    localStorage.setItem(STORAGE_KEYS.SHOW_QUIZ, JSON.stringify(showQuiz));
    localStorage.setItem(STORAGE_KEYS.SHOW_FLASHCARDS, JSON.stringify(showFlashCards));
    localStorage.setItem(STORAGE_KEYS.SAVED_STORIES, JSON.stringify(savedStories));
    localStorage.setItem(STORAGE_KEYS.SAVED_FLASHCARDS, JSON.stringify(savedFlashCards));
  }, [appLanguage, language, level, storyStyle, theme, showQuiz, showFlashCards, savedStories, savedFlashCards]);

  useEffect(() => {
    const root = window.document.documentElement;
    if (theme === 'dark') {
      root.classList.add('dark');
    } else {
      root.classList.remove('dark');
    }
  }, [theme]);

  // Sync saved status with current story ID
  useEffect(() => {
    if (savedStories.some(s => s.id === currentStoryId) && storyHistory.length > 0) {
      setSavedStories(prev => prev.map(s => 
        s.id === currentStoryId ? { ...s, history: storyHistory } : s
      ));
    }
  }, [storyHistory, currentStoryId]);

  const handleLoadingComplete = () => {
    if (pendingUpdate) {
      pendingUpdate();
    }
    setPendingUpdate(null);
    setIsFinishingLoading(false);
    setIsGenerating(false);
    setIsRewriting(false);
  };

  const handleGenerateNew = async () => {
    setIsGenerating(true);
    setIsRewriting(false);
    setIsFinishingLoading(false);
    setIsFocused(false);
    setError(null);
    setStoryHistory([]);
    setCurrentIndex(-1);

    setCurrentStoryId(generateId());

    try {
      const topic = storyDescription.trim() || (currentSuggestedTopics[0] || "A random adventure");
      const newStory = await generateStory(
        language, 
        level, 
        topic, 
        storyStyle, 
        appLanguage,
        showQuiz,
        showFlashCards
      );

      // Store the update action for later
      setPendingUpdate(() => () => {
        setStoryHistory([newStory]);
        setCurrentIndex(0);
        window.scrollTo({ top: 0, behavior: 'smooth' });
      });

      // Signal loading bar to finish
      setIsFinishingLoading(true);

    } catch (err: any) {
      setError(err.message || t.errorGenerating);
      setIsGenerating(false);
    }
  };

  const handleNextPage = async () => {
    if (currentIndex < storyHistory.length - 1) {
      setCurrentIndex(prev => prev + 1);
      return;
    }

    setIsGenerating(true);
    setError(null);
    try {
      const lastStory = storyHistory[storyHistory.length - 1];
      const nextPart = await generateStory(
        language, 
        level, 
        `Continuation of: ${lastStory.title}`, 
        storyStyle, 
        appLanguage, 
        showQuiz,
        showFlashCards,
        lastStory.content
      );
      setStoryHistory(prev => [...prev, nextPart]);
      setCurrentIndex(prev => prev + 1);
    } catch (err: any) {
      setError(err.message || t.errorGenerating);
    } finally {
      setIsGenerating(false);
    }
  };

  const handleLevelChange = async (newLevel: CEFRLevel) => {
    if (isGenerating || currentIndex < 0 || !storyHistory[currentIndex]) return;

    setLevel(newLevel);
    setIsGenerating(true);
    setIsRewriting(true);
    setIsFinishingLoading(false);
    setError(null);

    try {
      const currentStoryContent = storyHistory[currentIndex].content;
      const rewrittenStory = await generateStory(
        language,
        newLevel,
        storyDescription || "Rewritten Story", 
        storyStyle,
        appLanguage,
        showQuiz,
        showFlashCards,
        undefined, 
        currentStoryContent 
      );

      // Store update action
      setPendingUpdate(() => () => {
        setStoryHistory(prev => {
          const newHistory = [...prev];
          newHistory[currentIndex] = rewrittenStory;
          return newHistory;
        });
      });

      // Signal loading bar to finish
      setIsFinishingLoading(true);

    } catch (err: any) {
      setError(err.message || t.errorGenerating);
      setIsGenerating(false);
      setIsRewriting(false);
    }
  };

  const handlePrevPage = () => {
    if (currentIndex > 0) {
      setCurrentIndex(prev => prev - 1);
    }
  };

  const handleTopicClick = (topic: string) => {
    setStoryDescription((prev) => {
      const trimmed = prev.trim();
      if (!trimmed) return topic;
      const existing = trimmed.split(',').map(s => s.trim());
      if (existing.includes(topic)) return trimmed;
      return `${trimmed}, ${topic}`;
    });
  };

  const handleToggleBookmark = () => {
    if (savedStories.some(s => s.id === currentStoryId)) {
      setSavedStories(prev => prev.filter(s => s.id !== currentStoryId));
    } else {
      if (storyHistory.length === 0) return;

      const newSavedStory: SavedStory = {
        id: currentStoryId,
        createdAt: Date.now(),
        language,
        level,
        style: storyStyle,
        topic: storyDescription || currentSuggestedTopics[0],
        history: storyHistory,
        appLanguage
      };
      setSavedStories(prev => [newSavedStory, ...prev]);
    }
  };

  const handleFlashCardToggle = (word: string, translation: string, isSaved: boolean) => {
    const id = `${language}-${word}`; 

    if (isSaved) {
      setSavedFlashCards(prev => {
        if (prev.some(fc => fc.id === id)) return prev;
        return [{
          id,
          word,
          translation,
          language,
          createdAt: Date.now()
        }, ...prev];
      });
    } else {
      setSavedFlashCards(prev => prev.filter(fc => fc.id !== id));
    }
  };

  const handleDeleteSavedFlashCard = (id: string) => {
    setSavedFlashCards(prev => prev.filter(fc => fc.id !== id));
  };

  const handleLoadStory = (story: SavedStory) => {
    setLanguage(story.language);
    setLevel(story.level);
    setStoryStyle(story.style);
    setStoryDescription(story.topic);
    setStoryHistory(story.history);
    setCurrentStoryId(story.id);
    setCurrentIndex(story.history.length - 1);
    setError(null);
  };

  const handleDeleteSavedStory = (id: string) => {
    setSavedStories(prev => prev.filter(s => s.id !== id));
  };

  const currentStory = currentIndex >= 0 ? storyHistory[currentIndex] : null;
  const themeGradient = LANGUAGE_THEMES[language] || "from-indigo-500 to-purple-600";
  const isBookmarked = savedStories.some(s => s.id === currentStoryId);

  return (
    <div className="min-h-screen bg-[#F8FAFC] text-gray-900 font-sans dark:bg-[#0B1120] dark:text-gray-100 transition-colors duration-300 selection:bg-indigo-500/20">

      {/* App Header */}
      <header className={`sticky top-0 z-40 w-full transition-all duration-500 ease-in-out ${isFocused ? 'lg:-translate-y-full opacity-0 lg:opacity-0 pointer-events-none' : 'translate-y-0 opacity-100'}`}>
        {/* Glass Effect Background */}
        <div className="absolute inset-0 bg-white/70 backdrop-blur-xl border-b border-gray-200/50 dark:bg-[#0B1120]/70 dark:border-gray-800/50 support-[backdrop-filter]:bg-white/60" />

        <div className="relative mx-auto max-w-7xl px-4 py-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between">
            <div className="group flex items-center space-x-3 cursor-default">
              <div className="relative rounded-2xl bg-gradient-to-br from-indigo-500 to-indigo-600 p-2.5 text-white shadow-lg shadow-indigo-500/25 transition-all duration-300 group-hover:shadow-indigo-500/40 group-hover:scale-105">
                <BookMarked className="h-6 w-6" />
                <div className="absolute inset-0 rounded-2xl bg-white/20 opacity-0 transition-opacity duration-300 group-hover:opacity-100" />
              </div>
              <div className="flex flex-col">
                <h1 className="text-xl font-bold tracking-tight text-gray-900 dark:text-white leading-tight font-display">
                  {t.appTitle}
                </h1>
                <p className="hidden text-xs font-medium text-gray-500 dark:text-gray-400 sm:block">
                  {t.appSubtitle}
                </p>
              </div>
            </div>

            <div className="flex items-center gap-2">
              <button
                onClick={() => setIsFlashCardsOpen(true)}
                className="group relative rounded-xl p-2.5 text-gray-500 transition-all duration-300 hover:bg-white hover:text-indigo-600 hover:shadow-md hover:shadow-gray-200/50 dark:text-gray-400 dark:hover:bg-gray-800 dark:hover:text-indigo-400 dark:hover:shadow-none"
                title={t.savedFlashCards}
              >
                <SquareStack className="h-5 w-5 transition-transform duration-300 group-hover:scale-110 group-hover:-rotate-3" />
              </button>

              <button
                onClick={() => setIsLibraryOpen(true)}
                className="group relative rounded-xl p-2.5 text-gray-500 transition-all duration-300 hover:bg-white hover:text-indigo-600 hover:shadow-md hover:shadow-gray-200/50 dark:text-gray-400 dark:hover:bg-gray-800 dark:hover:text-indigo-400 dark:hover:shadow-none"
                title={t.savedStories}
              >
                <Library className="h-5 w-5 transition-transform duration-300 group-hover:scale-110 group-hover:-rotate-3" />
              </button>

              <div className="mx-2 h-6 w-px bg-gray-200 dark:bg-gray-800"></div>

              <button
                onClick={() => setIsSettingsOpen(true)}
                className="group relative rounded-xl p-2.5 text-gray-500 transition-all duration-300 hover:bg-white hover:text-indigo-600 hover:shadow-md hover:shadow-gray-200/50 dark:text-gray-400 dark:hover:bg-gray-800 dark:hover:text-indigo-400 dark:hover:shadow-none"
                title={t.settingsTitle}
              >
                <SettingsIcon className="h-5 w-5 transition-transform duration-300 group-hover:scale-110 group-hover:rotate-12" />
              </button>
            </div>
          </div>
        </div>
      </header>

      <main className={`mx-auto max-w-7xl px-4 py-8 sm:px-6 lg:px-8 transition-all duration-500 ease-[cubic-bezier(0.34,1.56,0.64,1)] ${isFocused ? 'pt-8' : ''}`}>
        <div className="grid grid-cols-1 gap-8 lg:grid-cols-12 relative items-start">

          {/* Sidebar - Controls */}
          <aside className={`transition-all duration-500 ease-[cubic-bezier(0.34,1.56,0.64,1)] ${isFocused ? 'hidden opacity-0 translate-x-[-20px]' : 'lg:col-span-4 xl:col-span-3 opacity-100 translate-x-0'}`}>
            <div className="sticky top-28 overflow-hidden rounded-3xl bg-white shadow-xl shadow-gray-200/50 ring-1 ring-gray-900/5 dark:bg-[#111827] dark:ring-gray-800 dark:shadow-none">
              <div className={`bg-gradient-to-r ${themeGradient} px-6 py-5 relative overflow-hidden`}>
                <div className="absolute inset-0 bg-white/10 opacity-50 backdrop-blur-3xl"></div>
                <h2 className="relative flex items-center text-lg font-bold text-white font-display">
                  <Sparkles className="mr-2 h-5 w-5" /> {t.storySettings}
                </h2>
              </div>

              <div className="p-6 space-y-6">
                <Selector<Language>
                  label={t.targetLanguage}
                  value={language}
                  options={LANGUAGES}
                  onChange={setLanguage}
                  getLabel={(opt) => languageLabels[opt]}
                  disabled={isGenerating}
                  icon={<Globe className="h-4 w-4 text-indigo-500" />}
                />

                <Selector<CEFRLevel>
                  label={t.languageLevel}
                  value={level}
                  options={LEVELS}
                  onChange={setLevel}
                  getLabel={(opt) => levelDescriptions[opt]}
                  disabled={isGenerating}
                  icon={<BarChart2 className="h-4 w-4 text-indigo-500" />}
                />

                <Selector<StoryStyle>
                  label={t.storyStyle}
                  value={storyStyle}
                  options={STORY_STYLES}
                  onChange={setStoryStyle}
                  getLabel={(opt) => storyStyleLabels[opt]}
                  disabled={isGenerating}
                  icon={<Feather className="h-4 w-4 text-indigo-500" />}
                />

                <div className="space-y-2.5">
                  <label className="text-sm font-bold text-gray-700 dark:text-gray-200 flex items-center gap-2">
                    <Tag className="h-4 w-4 text-indigo-500" />
                    {t.storyDescription}
                  </label>
                  <textarea
                    value={storyDescription}
                    onChange={(e) => setStoryDescription(e.target.value)}
                    placeholder={t.descPlaceholder}
